alter table monad_academy.submissions add column id_long bigint;
alter table monad_academy.user_task_progress add column id_long bigint;

with numbered as (
	select id, row_number() over (order by created_at, id)::bigint as new_id
	from monad_academy.users
)
update monad_academy.users target
set id_long = numbered.new_id
from numbered
where target.id = numbered.id;

with numbered as (
	select id, row_number() over (order by created_at, id)::bigint as new_id
	from monad_academy.tasks
)
update monad_academy.tasks target
set id_long = numbered.new_id
from numbered
where target.id = numbered.id;

with numbered as (
	select id, row_number() over (order by created_at, id)::bigint as new_id
