alter table monad_academy.email_verification_tokens
	add constraint fk_email_verification_tokens_user foreign key (user_id)
	references monad_academy.users (id) on delete cascade;
alter table monad_academy.audit_logs
	add constraint fk_audit_logs_user foreign key (user_id)
	references monad_academy.users (id) on delete set null;
alter table monad_academy.task_test_cases
	add constraint fk_task_test_cases_task foreign key (task_id)
	references monad_academy.tasks (id) on delete cascade;
alter table monad_academy.submissions
	add constraint fk_submissions_user foreign key (user_id)
	references monad_academy.users (id) on delete cascade;
alter table monad_academy.submissions
	add constraint fk_submissions_task foreign key (task_id)
	references monad_academy.tasks (id) on delete cascade;
alter table monad_academy.user_task_progress
	add constraint fk_user_task_progress_user foreign key (user_id)
	references monad_academy.users (id) on delete cascade;
alter table monad_academy.user_task_progress
	add constraint fk_user_task_progress_task foreign key (task_id)
	references monad_academy.tasks (id) on delete cascade;

alter table monad_academy.user_task_progress
	add constraint uk_user_task_progress_user_task unique (user_id, task_id);

create index idx_email_verification_tokens_user_id on monad_academy.email_verification_tokens (user_id);
